<div class="theme-option-body"><div class="theme-option-heading"><h2><?= CHtml::encode($theme['number'].' · '.$theme['title']) ?></h2><span class="status <?= $active===$key?'status-paid':'' ?>"><?= $active===$key?'فعال':CHtml::encode($theme['mode']) ?></span></div><p><?= CHtml::encode($theme['description']) ?></p><div class="theme-option-actions"><?= CHtml::link("شخصی‌سازی",array("adminTheme/customize","key"=>$key),array("class"=>"btn btn-outline btn-sm","data-pjax"=>"1")) ?><?= CHtml::link('نمایش زنده',ThemeService::previewUrl($key),array('class'=>'btn btn-outline btn-sm','target'=>'_blank','rel'=>'noopener','data-no-pjax'=>'1')) ?><?php if($active!==$key): ?><?= CHtml::beginForm(array('adminTheme/activate'),'post',array('data-confirm'=>'قالب «'.$theme['title'].'» برای همه بازدیدکنندگان فعال شود؟')) ?><?= CHtml::hiddenField('theme',$key) ?><?= CHtml::submitButton('فعال‌سازی قالب',array('class'=>'btn btn-primary btn-sm')) ?><?= CHtml::endForm() ?><?php else: ?><span class="theme-active-label">قالب فعال فروشگاه</span><?php endif; ?></div></div></article><?php endforeach; ?></div>
